sealed class CoreException(message: String): kotlin.Exception(message) {
        
        class ModelLoadException(message: String) : CoreException(message)
        
        class InferenceException(message: String) : CoreException(message)
        
        class DecryptionFailed(message: String) : CoreException(message)
        
        class EncryptionFailed(message: String) : CoreException(message)
        
        class InvalidKey(message: String) : CoreException(message)
        
        class ParseException(message: String) : CoreException(message)
        
        class TokenizerException(message: String) : CoreException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        
            return when(buf.getInt()) {
            1 -> CoreException.ModelLoadException(FfiConverterString.read(buf))
            2 -> CoreException.InferenceException(FfiConverterString.read(buf))
            3 -> CoreException.DecryptionFailed(FfiConverterString.read(buf))
            4 -> CoreException.EncryptionFailed(FfiConverterString.read(buf))
            5 -> CoreException.InvalidKey(FfiConverterString.read(buf))
            6 -> CoreException.ParseException(FfiConverterString.read(buf))
            7 -> CoreException.TokenizerException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: CoreException): ULong {
        return 4UL
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.ModelLoadException -> {
                buf.putInt(1)
                Unit
            }
            is CoreException.InferenceException -> {
                buf.putInt(2)
                Unit
            }
            is CoreException.DecryptionFailed -> {
                buf.putInt(3)
                Unit
            }
            is CoreException.EncryptionFailed -> {
                buf.putInt(4)
                Unit
            }
            is CoreException.InvalidKey -> {
                buf.putInt(5)
                Unit
            }
            is CoreException.ParseException -> {
                buf.putInt(6)
                Unit
            }
            is CoreException.TokenizerException -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




